typeSystemExample.source:
const std = @import("std");

fn max(comptime T: type, a: T, b: T) T {
    return if (a >= b) a else b;
}

pub fn main() void {
    std.debug.print("{d}\n", .{max(i32, 3, 7)});
    std.debug.print("{d}\n", .{max(f64, 1.5, 2.8)});
}

concurrencyExample.source:
const std = @import("std");

fn square(n: usize) usize {
    return n * n;
}

pub fn main() !void {
    var threads: [4]std.Thread = undefined;
    var results: [4]usize = undefined;

    for (0..4) |i| {
        threads[i] = try std.Thread.spawn(.{}, struct {
            fn run(idx: usize, res: *[4]usize) void {
                res[idx] = square(idx);
            }
        }.run, .{ i, &results });
    }
    for (&threads) |*t| t.join();

    for (results) |r| std.debug.print("{d} ", .{r});
}

